{
  "title": "A slower, tastier Mexico City",
  "summary": "Swap the grand halls for market bustle, a leafy wander, and a long canal ride, with vegan tacos to keep everyone smiling.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The one keeper, and rightly so: old stones, big stories, and a photo spot that earns its fame.",
      "start": "09:00"
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "Swapped in for a palace: market chatter, strange fruits, and the city's real pulse.",
      "start": "11:00"
    },
    {
      "poi_id": "p15",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch with a clear conscience and a full belly: vegan tacos that even carnivores eye with envy.",
      "start": "12:30"
    },
    {
      "poi_id": "p10",
      "kind": "activity",
      "must_do_id": null,
      "note": "A gentle wander through Roma Norte instead of another museum: street art, coffee smells, and zero queues.",
      "start": "14:00"
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "The big swap: floating gardens and mariachi instead of castle steps. Slow water, loud colour.",
      "start": "16:00"
    },
    {
      "poi_id": "p17",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at a place that treats vegetables like royalty; a long, unhurried end to the day.",
      "start": "19:30"
    }
  ]
}
